import { separationPanel, createComparisonPlayer } from './separation-panel.js';
import { icon as I } from './icons.js';
import { createPanelLayout, panelResizer } from './layout.js';
import { audibleLines, createTimelineDrag, moveClip, preserveSource, reorderSpeaker, toggleTrack } from './timeline-edit.js';
import { createMonitor } from './monitor.js';
import { timingInfo, playbackRate, timingFix, exportIssues } from './timing.js';

const root=document.querySelector('#root');
const S={p:null,models:[],health:null,jobs:[],projects:[],selected:null,tab:'Timeline',modal:null,dirty:false,busy:'',error:'',notice:'',time:1.4,playing:false,zoom:1,listen:'original',muted:false,history:[],future:[],editVersion:0,saving:false,trimming:false,saveError:'',autosave:true};
try{S.autosave=localStorage.getItem('koto-autosave')!=='off';}catch{/* Default to autosave when preferences are unavailable. */}
const separationState={start:0,end:30,resultId:null,lineId:null};
let separationCatalog=null;
const comparison=createComparisonPlayer({url:name=>asset(name),onError:message=>{S.error=message;renderToasts();},onUpdate:updateSeparationPlayer,pauseMonitor:()=>{S.playing=false;$('#video')?.pause();monitor.stop();updateTransport();}});
const stages=[['prepare','Prepare','layers'],['separate','Separate','audio'],['transcribe','Transcribe','file'],['diarize','Speakers','mic'],['translate','Translate','subtitles'],['synthesize','Generate','sparkles']];
const caps={separate:'separation',transcribe:'transcription',diarize:'diarization',translate:'translation',synthesize:'synthesis'};
const H=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cp=v=>structuredClone(v);
const $=s=>root.querySelector(s);
const line=()=>S.p?.dialogue.find(l=>l.id===S.selected);
const speaker=()=>S.p?.speakers.find(s=>s.id===(line()?.speaker??S.voiceSpeaker))??S.p?.speakers[0];
const duration=()=>S.p?.media?.duration??Math.max(18,...(S.p?.dialogue.map(l=>l.end+3)??[]));
const active=j=>['running','queued'].includes(j.status);
const locked=()=>Boolean(S.busy)||S.jobs.some(active);
const asset=name=>name?`/api/projects/${S.p.id}/assets/${name.split('/').map(encodeURIComponent).join('/')}`:'';
const time=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;
const precise=t=>`${Math.floor(t/3600).toString().padStart(2,'0')}:${time(t%3600)}.${Math.floor(t%1*1000).toString().padStart(3,'0')}`;
const disabled=value=>value?' disabled':'';
const button=(act,html,cls='icon-button',title='',off=false,extra='')=>`<button data-act="${act}" class="${cls}" title="${H(title)}"${disabled(off)} ${extra}>${html}</button>`;
const opt=(value,label,selected)=>`<option value="${H(value)}"${selected?' selected':''}>${H(label)}</option>`;
const field=(label,name,value,type='text',extra='')=>`<label class="field-label">${H(label)}<input data-field="${name}" type="${type}" value="${H(value)}" ${extra}></label>`;
const select=(label,name,options)=>`<label class="field-label">${H(label)}<select data-field="${name}">${options}</select></label>`;

async function api(path,body,method='POST'){
  const init=body===undefined?{}:{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)};
  const r=await fetch('/api'+path,init);if(!r.ok){let e;try{e=await r.json();}catch{e={detail:r.statusText};}throw new Error(typeof e.detail==='string'?e.detail:JSON.stringify(e.detail));}return r.json();
}
let autosaveTimer=null,savePending=null;
function adopt(p){comparison.stop();separationState.resultId=null;clearTimeout(autosaveTimer);S.editVersion++;S.p=p;S.dirty=false;S.saveError='';S.history=[];S.future=[];if(!p.dialogue.some(l=>l.id===S.selected))S.selected=p.dialogue[0]?.id??null;localStorage.setItem('koto-project',p.id);}
function scheduleAutosave(){
  clearTimeout(autosaveTimer);
  if(!S.autosave||!S.dirty||S.saveError)return;
  autosaveTimer=setTimeout(()=>{
    if(!S.autosave||!S.dirty)return;
    if(locked()||timelineDrag.dragging||panelLayout.dragging||S.trimming){scheduleAutosave();return;}
    return save(false).catch(error=>{S.error='Autosave failed: '+error.message+'. Your edits are still here; use Save to retry.';renderToasts();});
  },1200);
}
function markDirty(){S.editVersion++;S.dirty=true;S.saveError='';scheduleAutosave();updateDirty();}
function edit(fn,redraw=false){if(locked())return;S.history.push(cp(S.p));if(S.history.length>30)S.history.shift();S.future=[];fn(S.p);markDirty();if(redraw)render();}
function saveStatus(){return S.saving?'Saving changes…':S.saveError?'Save failed · changes retained':S.dirty?'Unsaved changes':'Project saved locally';}
function updateDirty(){const b=$('[data-act="save"]');if(b)b.innerHTML=I('save')+(S.saving?'Saving…':S.dirty?'Save changes':'Saved');const status=$('#save-status');if(status)status.textContent=saveStatus();}
async function save(flush=true){
  clearTimeout(autosaveTimer);
  if(savePending){await savePending;return flush&&S.dirty?save(true):S.p;}
  if(!S.p||!S.dirty)return S.p;
  const pid=S.p.id,version=S.editVersion;
  const {revision,name,dialogue,speakers,models,settings}=cp(S.p);
  S.saving=true;S.saveError='';updateDirty();
  const pending=(async()=>{
    try{
      const saved=await api(`/projects/${pid}`,{revision,name,dialogue,speakers,models,settings},'PATCH');
      if(S.p?.id!==pid)return saved;
      if(S.editVersion===version){S.p=saved;S.dirty=false;}
      else{S.p.revision=saved.revision;S.p.assets=saved.assets;}
      if(S.error.startsWith('Autosave failed:')){S.error='';renderToasts();}
      return S.p;
    }catch(error){if(S.p?.id===pid)S.saveError=error.message;throw error;}
    finally{S.saving=false;updateDirty();if(S.p?.id===pid&&S.dirty&&!S.saveError)scheduleAutosave();}
  })();
  savePending=pending;
  try{await pending;}finally{if(savePending===pending)savePending=null;}
  return flush&&S.dirty?save(true):S.p;
}
function focusSelectedClip(){const clip=Array.from(root.querySelectorAll('[data-act="select-line"]')).find(el=>el.dataset.id===S.selected);clip?.focus({preventScroll:true});}
function deleteSelectedClip(){
  if(!S.p||locked())return false;
  const index=S.p.dialogue.findIndex(l=>l.id===S.selected);if(index<0)return false;
  edit(p=>{p.dialogue.splice(index,1);S.selected=p.dialogue[Math.min(index,p.dialogue.length-1)]?.id??null;},true);
  focusSelectedClip();notify('Clip deleted · Ctrl+Z to undo');return true;
}
async function safe(fn,label='Working'){if(S.busy)return;S.busy=label;S.error='';renderToasts();try{await fn();}catch(e){S.error=e.message;}finally{S.busy='';render();}}
function notify(message){S.notice=message;renderToasts();clearTimeout(notify.timer);notify.timer=setTimeout(()=>{S.notice='';renderToasts();},4000);}
function updateJobs(jobs){
  const previous=new Map(S.jobs.map(j=>[j.id,j]));S.jobs=jobs;
  for(const j of jobs){if(!previous.has(j.id)||!active(previous.get(j.id))||active(j))continue;
    const label=j.kind[0].toUpperCase()+j.kind.slice(1);
    if(['failed','interrupted'].includes(j.status)){S.error=`${label} ${j.status}: ${j.message}`;S.tab='Jobs';renderToasts();}
    else if(j.status==='completed'){if(j.kind==='download_separation_model')void api('/separation/models').then(c=>{separationCatalog=c;if(S.modal==='separation')renderModal();}).catch(e=>{S.error=e.message;renderToasts();});if(j.kind==='separate'){comparison.stop();separationState.resultId=j.result?.separation_id;}if(j.kind==='synthesize'){S.listen='dub';syncDub();notify('Voices ready · English mix selected. Press Play to review.');}else if(j.kind==='export'&&j.result?.warnings?.length)notify('Export complete with timing warnings · review in Jobs.');else notify(`${label} complete`);}
    else if(j.status==='cancelled')notify(`${label} cancelled`);
  }
}
async function job(kind,options={}){if(locked())return;await safe(async()=>{
  await save();S.tab='Jobs';
  const submitted=await api(`/projects/${S.p.id}/jobs`,{kind,options});
  S.jobs=[{id:submitted.id,kind,status:'queued',progress:0,message:'Waiting for worker',result:{}},...S.jobs];render();
  updateJobs(await api(`/projects/${S.p.id}/jobs`));
  const latest=S.jobs.find(j=>j.id===submitted.id);
  if(latest&&active(latest))notify(`${kind[0].toUpperCase()+kind.slice(1)} queued — progress is shown in Jobs`);
},'Queuing job');}

function imageSubtitleSelected(){return ['hdmv_pgs_subtitle','dvd_subtitle','dvb_subtitle'].includes(S.p.media?.streams.find(s=>s.index===S.p.settings.subtitle_stream)?.codec);}
function prepareOverlay(){
  if(!S.p.media||S.p.assets.preview)return '';
  const j=S.jobs.find(j=>j.kind==='prepare'),processing=j&&active(j),failed=j&&['failed','interrupted'].includes(j.status);
  const title=processing?(j.status==='queued'?'Prepare queued':`Preparing media · ${Math.round(j.progress*100)}%`):failed?'Prepare failed':'Source is ready';
  const message=processing?j.message:failed?j.message:imageSubtitleSelected()?'Selected subtitles are images. Prepare without them, then import an SRT/ASS file if needed.':'Prepare media to create a playback preview.';
  return `<div class="prepare-overlay ${failed?'prepare-failed':''}" role="status">${I(processing?'loader':failed?'activity':'film',24,processing?'spin':'')}<strong>${title}</strong><span>${H(message)}</span>${processing?`<div class="progress-bar"><i style="width:${j.progress*100}%"></i></div><small>Full-length preview encoding can take several minutes.</small>${button('cancel',I('x',12)+'Cancel Prepare','secondary','Cancel',false,`data-id="${j.id}"`)}`:button(imageSubtitleSelected()?'prepare-no-subtitles':'job',I('layers')+(imageSubtitleSelected()?'Prepare without image subtitles':failed?'Retry Prepare':'Prepare media'),'primary','Prepare',locked(),'data-kind="prepare"')}${button('tab','View Jobs','text-button','Processing details',false,'data-tab="Jobs"')}</div>`;
}
function queueSummary(){
  const j=S.jobs.find(active)??S.jobs[0];
  if(!j)return `<div class="queue-empty">${I('checked',15)}<span>Ready when you are</span></div>`;
  return `<div class="running-card ${['failed','interrupted'].includes(j.status)?'queue-failed':''}"><div>${I(active(j)?'loader':j.status==='completed'?'checked':'activity',13,active(j)?'spin':'')}<strong>${H(j.kind)}</strong><span>${active(j)?Math.round(j.progress*100)+'%':H(j.status)}</span></div>${active(j)?`<div class="progress-bar"><i style="width:${j.progress*100}%"></i></div>`:''}<p>${H(j.message)}</p>${active(j)?button('cancel',I('x',12)+'Cancel job','text-button','Cancel',false,`data-id="${j.id}"`):''}${button('tab','View Jobs','text-button','Processing details',false,'data-tab="Jobs"')}</div>`;
}
function choose(accept){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>resolve(input.files[0]??null);input.oncancel=()=>resolve(null);input.click();});}
async function importFile(route,accept,fields={},file=null){file=file??await choose(accept);if(!file)return;await safe(async()=>{await save();if(route==='media'&&S.p.media)adopt(await api('/projects',{name:file.name}));const body=new FormData();body.append('file',file);Object.entries(fields).forEach(([k,v])=>body.append(k,v));const r=await fetch(`/api/projects/${S.p.id}/${route}`,{method:'POST',body});if(!r.ok)throw new Error((await r.json()).detail);adopt(await r.json());if(route==='media'){S.time=0;S.playing=false;S.selected=null;}notify(route==='media'?'Source imported. Choose tracks, then Prepare.':'File imported and saved');},`Importing ${file.name}`);}
function seek(t){S.time=Math.max(0,Math.min(duration(),t));const v=$('#video');if(v)v.currentTime=S.time;syncDub();updateTransport();}
function updateTransport(){const head=$('.playhead');if(head)head.style.left=`${186+S.time*pps()}px`;const code=$('#timecode');if(code)code.innerHTML=`${precise(S.time)}<span>/ ${precise(duration())}</span>`;const caption=$('.preview-caption');if(caption)caption.style.visibility=S.p.settings.subtitles_visible===false?'hidden':'visible';if(caption)caption.textContent=S.p.dialogue.find(l=>l.start<=S.time&&l.end>=S.time)?.translation??'';const b=$('[data-act="play"]');if(b)b.innerHTML=I(S.playing?'pause':'play',17);}
function pps(){return Math.max(1,($('.timeline-scroll')?.clientWidth??1000)-186)/duration()*S.zoom;}
function play(){monitor.activate();const v=$('#video');if(v){if(S.playing)v.pause();else v.play().catch(e=>{S.error=e.message;renderToasts();});}else{S.playing=!S.playing;syncDub();updateTransport();}}
function syncDub(){const v=$('#video');if(v)v.muted=true;if(S.p)monitor.sync(S.p,S.time,S.listen,S.playing,S.muted);else monitor.stop();}
let audition;
function preview(name,rate=1){if(!name)return;audition?.pause();audition=new Audio(asset(name));audition.playbackRate=rate;audition.play().catch(e=>{S.error=e.message;renderToasts();});}
function done(kind){if(S.p.demo)return false;if(kind==='prepare')return Boolean(S.p.assets.preview||S.p.assets.original_audio);if(kind==='separate')return Boolean(S.p.assets.background);if(kind==='transcribe')return S.p.dialogue.some(l=>l.source);if(kind==='diarize')return S.jobs.some(j=>j.kind===kind&&j.status==='completed');if(kind==='translate')return Boolean(S.p.dialogue.length)&&S.p.dialogue.every(l=>l.translation);return Boolean(S.p.dialogue.length)&&S.p.dialogue.every(l=>l.audio);}
const station=()=>`<div class="station"><img src="/assets/station.svg" alt="Illustrated rainy train station, sample artwork"><span class="artwork-label">SAMPLE ARTWORK · IMPORT VIDEO TO BEGIN</span></div>`;
function wave(name,color,sample=false){return `<div class="wave-container" data-wave="${H(name??'')}" data-color="${color}" data-sample="${sample}"><svg class="waveform" viewBox="0 0 720 36" preserveAspectRatio="none"><line x1="0" x2="720" y1="18" y2="18" stroke="${color}" opacity=".2"/></svg></div>`;}
const peaksCache=new Map();
async function drawWaves(){for(const el of root.querySelectorAll('[data-wave]')){const name=el.dataset.wave,color=el.dataset.color;let peaks=[];try{if(!name&&el.dataset.sample==='true')peaks=Array.from({length:180},(_,i)=>.08+Math.abs(Math.sin(i*1.71)*Math.cos(i*.23))*.8);else if(name){const key=asset(name);if(!peaksCache.has(key)){const r=await fetch(key.replace('/assets/','/waveform/'));if(r.ok)peaksCache.set(key,await r.json());}peaks=peaksCache.get(key)??[];}}catch{/* waveform never blocks editing */}if(!el.isConnected)continue;el.querySelector('svg').innerHTML=`<line x1="0" x2="720" y1="18" y2="18" stroke="${color}" opacity=".2"/>`+peaks.map((p,i)=>`<rect x="${i*720/peaks.length}" y="${18-Math.max(1,p*15)}" width="${Math.max(1,720/peaks.length*.55)}" height="${Math.max(2,p*30)}" fill="${color}" opacity=".85"/>`).join('');}}

function render(){
  if(!S.p){root.innerHTML=`<div class="boot"><div class="brand-mark">K</div><h1>KOTO Studio</h1><p>${H(S.error||'Opening your local workspace…')}</p>${S.error?button('reload','Retry connection','secondary'):I('loader',20,'spin')}</div>`;return;}
  const p=S.p,l=line(),sp=speaker();
  const oldVideo=$('#video'),oldDub=$('#dub'),scroll=$('.timeline-scroll')?.scrollLeft??0;
  root.innerHTML=`<div class="app-shell">
    <header class="app-header"><button data-act="help" class="brand"><span class="brand-mark">K</span><span>KOTO<span class="brand-studio">STUDIO</span></span></button><div class="header-divider"></div>${button('projects',`<span>${H(p.name)}</span>${I('down',13)}${p.demo?'<span class="tiny-tag">SAMPLE</span>':''}`,'header-project','Open project library')}<div class="header-right"><span class="local-pill"><span class="status-dot"></span>LOCAL WORKSPACE</span>${button('help',I('more',20),'icon-button','Help & setup')}${button('save',I('save')+(S.dirty?'Save changes':'Saved')+(!S.dirty?I('check',12):''),'save-button','Save (Ctrl+S)',locked())}${button('export',I('download',15)+'Export'+I('down',12),'primary render-button','Export settings',Boolean(S.busy))}</div></header>
    <nav class="workflow"><div class="workflow-label">${I('sparkles',15)}<span>DUBBING PIPELINE</span></div>${stages.map(([kind,label,ic],i)=>{const processing=S.jobs.some(j=>j.kind===kind&&active(j));return `<div class="stage-wrap">${button('job',`<span class="stage-number">${processing?I('loader',12,'spin'):done(kind)?I('check',12):i+1}</span>${I(ic,15)}<span>${label}</span>`,`stage ${done(kind)?'stage-done':''} ${processing?'stage-active':''}`,label,locked()||(!p.media&&['prepare','separate','transcribe','diarize'].includes(kind)),`data-kind="${kind}"`)}${i<5?I('chevron',12,'stage-chevron'):''}</div>`;}).join('')}</nav>
    <main class="workspace"><aside class="left-panel"><div class="panel-title"><span>PROJECT MEDIA</span>${button('import-media',I('plus',15),'icon-button','Import video',locked())}</div>${button('import-media',`<span class="import-icon">${I('upload',19)}</span><strong>Import source video</strong><span>Drop a file or browse</span><small>MKV · MP4 · MOV · WEBM</small>`,'import-card','Import source video',locked())}${p.media?`<div class="media-tree"><div class="media-file">${I('down',12)}${I('film',15)}<span title="${H(p.media.name)}">${H(p.media.name)}</span></div>${p.media.streams.map(s=>`<div class="media-stream">${I(s.type==='video'?'film':s.type==='audio'?'audio':'subtitles',13)}<span>${H(s.language==='und'?s.type:s.language.toUpperCase())}<small>${H(s.codec)}${s.width?` · ${s.width}×${s.height}`:s.channels?` · ${s.channels}ch`:''}</small></span><span class="stream-index">${s.index}</span></div>`).join('')}</div>`:`<div class="empty-media">${I('film',15)}<span>No source imported</span></div>`}${button('sub-en',I('subtitles')+'Import English subtitles'+I('plus',13),'text-button import-subtitle','Import English subtitles',locked())}${button('sub-ja',I('file')+'Import Source subtitles · JP/CN'+I('plus',13),'text-button import-subtitle','Import Source subtitles · JP/CN',locked())}
    <div class="panel-title section-gap"><span>SPEAKERS</span><span class="count">${p.speakers.length}</span>${button('add-speaker',I('plus',15),'icon-button','Add speaker',locked())}</div><div class="speaker-list">${p.speakers.map((s,i)=>button('speaker',`<span class="avatar" style="--speaker-color:${s.color}">${I('mic',17)}<small>${String(i+1).padStart(2,'0')}</small></span><span class="speaker-info"><strong>${H(s.name)}</strong><small>${s.use_source_reference?'Original voice reference':s.reference?'Reference attached':s.voice.adapter?H(S.models.find(m=>m.id===s.voice.adapter)?.label??s.voice.adapter):'Default project voice'}</small></span><span class="speaker-count">${p.dialogue.filter(l=>l.speaker===s.id).length}</span>`,`speaker-card ${sp?.id===s.id?'selected-speaker':''}`,'Speaker voice',false,`data-id="${H(s.id)}"`)).join('')}</div><div class="left-spacer"></div><div class="queue-summary"><div class="panel-title"><span>PROCESSING QUEUE</span><span class="count">${S.jobs.filter(active).length}</span></div>${queueSummary()}</div>${button('models',`${I('cpu',17)}<span><strong>Model manager</strong><small>${S.models.filter(m=>m.available).length} workers available</small></span>${I('chevron')}`,'model-footer','Configure local models')}</aside>
    <section class="center-panel"><div class="preview-toolbar"><div class="preview-label"><span class="status-dot"></span>PROGRAM MONITOR</div><div class="compare-toggle">${button('original','Original',S.listen==='original'?'active':'')}${button('dub','English mix',S.listen==='dub'?'active':'','Preview live English mix',!p.assets.original_audio&&!p.assets.background&&!p.dialogue.some(l=>l.audio))}</div>${button('fullscreen',I('maximize'),'icon-button','Full screen preview')}</div><div class="preview-frame ${p.settings.video_visible===false?'video-hidden':''}">${p.assets.preview?`<video id="video" src="${asset(p.assets.preview)}" playsinline></video>`:station()}${p.settings.video_visible===false?'<div class="hidden-video-label">Video hidden</div>':''}${prepareOverlay()}${p.demo?'<div class="preview-caption"></div>':''}<span class="preview-quality">${p.media?'PREVIEW':'ILLUSTRATION'}<span>FIT</span></span></div><div class="transport"><span class="timecode" id="timecode"></span><div class="transport-buttons">${button('prev',I('prev',15),'','Previous dialogue')}${button('play',I(S.playing?'pause':'play',17),'play-button','Play / pause (Space)')}${button('next',I('next',15),'','Next dialogue')}</div><div class="transport-end">${button('mute',I('volume',15),S.muted?'muted':'','Mute / unmute')}<span class="fps">${p.media?'SOURCE PREVIEW':'SAMPLE'}</span></div></div>
    <div class="dialogue-heading"><span>${I('file')}DIALOGUE EDITOR</span><div>${l?`<small>LINE ${String(p.dialogue.indexOf(l)+1).padStart(2,'0')} / ${p.dialogue.length}</small>`:''}${button('add-line',I('plus',13)+'Add line','text-button','Add dialogue',locked())}</div></div>${l?panelResizer('dialogue'):''}${dialogueEditor(l,sp)}</section>
    <aside class="right-panel"><div class="panel-title"><span>INSPECTOR</span>${I('settings')}</div><div class="inspector-tabs">${button('voice-tab','Voice',S.tab==='Voices'?'active':'')}${button('timeline-tab','Clip',S.tab!=='Voices'?'active':'')}</div>${inspector(l,sp)}</aside>
    <section class="timeline-panel"><div class="timeline-toolbar"><div class="timeline-tabs">${[['Timeline','layers'],['Dialogue','subtitles'],['Jobs','activity']].map(([t,ic])=>button('tab',`${I(ic)} ${t}${t==='Dialogue'?`<span>${p.dialogue.length}</span>`:''}${t==='Jobs'&&S.jobs.some(j=>j.status==='failed')?'<i class="error-dot"></i>':''}`,(S.tab===t||t==='Timeline'&&S.tab==='Voices')?'active':'','',false,`data-tab="${t}"`)).join('')}</div><div class="timeline-tools">${button('undo',I('undo'),'icon-button','Undo (Ctrl+Z)',locked()||!S.history.length)}${button('redo',I('redo'),'icon-button','Redo (Ctrl+Shift+Z)',locked()||!S.future.length)}<span class="tool-divider"></span>${button('zoom-out',I('minus'),'icon-button','Zoom out')}<input aria-label="Timeline zoom" data-field="zoom" type="range" min="1" max="32" step=".5" value="${S.zoom}">${button('zoom-in',I('zoom'),'icon-button','Zoom in')}${button('fit','FIT','fit-button','Fit timeline')}</div></div>${S.tab==='Dialogue'?dialogueTable():S.tab==='Jobs'?jobsView():'<div class="timeline-scroll"><div class="timeline-content"></div></div>'}</section>
    ${['left','right','timeline'].map(panelResizer).join('')}</main><footer class="statusbar"><div><label class="autosave-toggle" title="Save automatically after a short pause in editing"><input type="checkbox" data-field="autosave"${S.autosave?' checked':''}>Autosave</label><span class="status-dot"></span><span id="save-status">${H(saveStatus())}</span><span class="footer-divider"></span><span>${p.media?`${Math.round(duration())}s source`:'Sample project'}</span><span class="footer-divider"></span><span>${p.dialogue.length} dialogue lines</span></div><div>${I('cpu',12)}<span>${S.health?.gpu?`${H(S.health.gpu.name)} · ${Math.round(S.health.gpu.vram_mb/1024)} GB`:'No NVIDIA GPU detected on this host'}</span><span class="footer-divider"></span><span>v${H(S.health?.version??'0.2.5')}</span></div></footer></div><div id="modal-root"></div><div id="toast-root"></div>`;
  const newVideo=$('#video'),newDub=$('#dub');if(oldVideo&&newVideo&&oldVideo.getAttribute('src')===newVideo.getAttribute('src'))newVideo.replaceWith(oldVideo);if(oldDub&&newDub&&oldDub.getAttribute('src')===newDub.getAttribute('src'))newDub.replaceWith(oldDub);
  const v=$('#video');if(v){v.muted=true;v.onloadedmetadata=()=>{v.currentTime=Math.min(S.time,v.duration);if(S.playing)v.play().catch(()=>{});};v.ontimeupdate=()=>{S.time=v.currentTime;syncDub();updateTransport();};v.onplay=()=>{S.playing=true;syncDub();updateTransport();};v.onpause=()=>{if(v.isConnected){S.playing=false;syncDub();updateTransport();}};v.onended=()=>{S.playing=false;syncDub();updateTransport();};if(S.playing)v.play().catch(()=>{});}
  panelLayout.refresh();renderTimeline();if($('.timeline-scroll'))$('.timeline-scroll').scrollLeft=scroll;renderModal();renderToasts();updateTransport();syncDub();void drawWaves();
}

function timingBadge(l){const t=timingInfo(S.p,l);return `<span class="timing-hint timing-${t.status}" title="${H(t.label+(t.measured?'':'. Rough word-count estimate; actual delivery varies.'))}">${I('clock',11)}${H(t.label)}</span>`;}
function timingActions(l){const fix=timingFix(S.p,l);return fix?`<div class="timing-actions">${fix.kind?button('fix-timing',fix.label,'secondary','Apply this timing change; the original take is kept',locked(),`data-id="${H(l.id)}"`):`<small>${H(fix.reason)}</small>`}</div>`:'';}
function alternativesFields(l){
  const data=l.alternatives,basis=data?.basis;
  const valid=basis&&['source','subtitle','translation','start','end'].every(k=>(basis[k]??null)===(l[k]??null));
  const suggestions=valid&&Array.isArray(data?.suggestions)?data.suggestions.filter(s=>typeof s.text==='string'):[];
  return `<div class="adaptation-tools">${button('suggest-alternatives',I('sparkles',12)+'Suggest alternatives','text-button','Run the local translation model for this clip only',locked()||!(l.source||l.subtitle||l.translation))}<small>Runs for this clip only · keeps your text until you choose</small>${suggestions.length?`<div class="translation-options">${suggestions.map((s,i)=>`<div class="translation-option"><p>${H(s.text)}</p><small>${H(timingInfo(S.p,l,s.text).label)}</small>${button('use-alternative','Use this','text-button','Replace English adaptation',locked(),`data-index="${i}"`)}</div>`).join('')}</div>`:''}</div>`;
}
function refreshTiming(){const hint=$('#timing-hint');if(hint&&line())hint.innerHTML=timingBadge(line());for(const node of root.querySelectorAll('[data-timing-id]')){const l=S.p.dialogue.find(l=>l.id===node.dataset.timingId);if(l){const t=timingInfo(S.p,l);node.className='clip-timing-dot timing-'+t.status;node.title=t.label;}}}
function dialogueEditor(l,sp){if(!l)return `<div class="no-dialogue">${I('subtitles',25)}<p>Select a dialogue clip, import subtitles, or add your first line.</p>${button('add-line',I('plus',13)+'Add dialogue','secondary','',locked())}</div>`;return `<fieldset class="dialogue-editor"${disabled(locked())}><div class="line-meta"><span class="speaker-dot" style="background:${sp.color}"></span><select aria-label="Dialogue speaker" data-field="line.speaker">${S.p.speakers.map(s=>opt(s.id,s.name,s.id===l.speaker)).join('')}</select><span class="line-range">${time(l.start)} — ${time(l.end)}</span><span class="take-status ${l.audio?'ready':''}">${I(l.audio?'check':'circle',10)}${l.audio?'Voice ready':'Awaiting voice'}</span>${button('delete-line',I('trash',13),'icon-button delete-line','Delete selected clip (Delete / Backspace)')}</div><div class="text-columns"><label><span>SOURCE DIALOGUE <small>EDITABLE</small></span><textarea data-field="line.source" aria-label="Source dialogue" placeholder="Recognize speech or enter Japanese / Chinese…">${H(l.source)}</textarea></label><label><span>ENGLISH ADAPTATION <small>EDITABLE</small></span><textarea data-field="line.translation" aria-label="English adaptation" placeholder="Translate or write the English line…">${H(l.translation)}</textarea></label></div>${l.subtitle?`<div class="subtitle-reference">${I('subtitles',12)}<span>Subtitle reference</span><p>${H(l.subtitle)}</p>${button('use-subtitle',I('chevron',13),'','Use subtitle as English adaptation')}</div>`:''}${alternativesFields(l)}<div class="line-bottom"><span id="timing-hint">${timingBadge(l)}</span><div>${button('preview-take',I('play',12)+'Preview take','secondary','Preview take',!l.audio)}${button('generate-line',I('sparkles',13)+'Generate line','accent-button','Generate selected line',!l.translation)}</div></div></fieldset>`;}
function modelFields(adapter,settings,prefix){return (adapter?.fields??[]).map(f=>f.type==='select'?select(f.label,`${prefix}.${f.key}`,f.options.map(v=>opt(v,v,v===(settings[f.key]??f.default))).join('')):field(f.label,`${prefix}.${f.key}`,settings[f.key]??f.default,f.type==='number'?'number':'text',f.type==='number'?'step="any"':'')).join('');}
function conversionFields(sp){const choices=S.models.filter(m=>m.capability==='voice_conversion');if(!choices.length)return '';const selection=sp.voice.conversion;return `<div class="inspector-section-title divider-top">${I('audio',13)}VOICE CONVERSION</div>${select('After synthesis','speaker-conversion',opt('','Use project conversion',!selection&&!sp.voice.conversion_disabled)+opt('none','No conversion',sp.voice.conversion_disabled)+choices.map(m=>opt(m.id,m.label,m.id===selection?.id)).join(''))}${selection?modelFields(choices.find(m=>m.id===selection.id),selection.settings,'conversion'):''}`;}
function projectConversionCard(){const choices=S.models.filter(m=>m.capability==='voice_conversion');const selection=S.p.models.voice_conversion;return `<fieldset class="model-card"${disabled(locked())}><div class="model-card-heading">${I('audio',16)}<strong>Voice conversion · optional</strong></div>${select('Process TTS output with','project-conversion',opt('','No conversion',!selection)+choices.map(m=>opt(m.id,m.label,m.id===selection?.id)).join(''))}<p>${choices.length?'Convert synthesized English using an installed local worker. Override the model per speaker in the Voice inspector.':'Add a voice_conversion worker to models/adapters.json to enable RVC or another converter.'}</p>${selection?modelFields(choices.find(m=>m.id===selection.id),selection.settings,'model.voice_conversion'):''}</fieldset>`;}
function referenceFields(sp){
  const source=sp.use_source_reference,ref=source?sp.source_reference?.asset:sp.reference;
  return `<label class="check-field"><input type="checkbox" data-field="speaker.use_source_reference"${source?' checked':''}>Use this speaker's original dialogue as voice reference</label><label class="field-label">${source?'Original speaker reference':'Uploaded voice sample'}<span class="reference-box">${ref?wave(ref,sp.color)+button('preview-reference',I('play',13),'icon-button','Preview reference'):`<span>${I('audio',20)}${source?'Built from non-overlapping original lines':'Clean speech · 3–120 seconds'}</span>`}${source?button('build-reference',I('audio',12)+(ref?'Rebuild reference':'Build reference'),'text-button','Build from original dialogue',!S.p.assets.original_audio&&!S.p.assets.vocals):button('reference',I('upload',12)+(ref?'Replace sample':'Attach sample'),'text-button')}</span></label><p class="inspector-note">${source?'Generate builds a reference automatically from up to 12 seconds of this speaker’s original dialogue. Check assignments first. Run Install-Reference-Voices.cmd for XTTS. Voice matching is approximate.':'Reference-conditioned models use this sample. Piper uses a fixed pretrained voice.'}</p>`;
}
function invalidateSpeakerTakes(p,id){for(const l of p.dialogue)if(l.speaker===id&&l.audio?.kind==='generated'){l.audio=null;l.warning='Voice changed. Regenerate this line.';}}
function inspector(l,sp){const p=S.p;return `<fieldset class="inspector-content"${disabled(locked())}>${S.tab==='Voices'&&sp?`<div class="inspector-section-title">${I('mic',13)}SPEAKER VOICE</div>${field('Speaker name','speaker.name',sp.name)}${select('Synthesis adapter','speaker.adapter',opt('','Use project default',!sp.voice.adapter)+S.models.filter(m=>m.capability==='synthesis').map(m=>opt(m.id,m.label+(!m.available?' · not installed':''),m.id===sp.voice.adapter)).join(''))}${modelFields(S.models.find(m=>m.id===(sp.voice.adapter??p.models.synthesis.id)),{...p.models.synthesis.settings,...sp.voice.settings},'voice')}${referenceFields(sp)}${button('generate-speaker',I('sparkles',13)+'Generate speaker','secondary full-width','Generate missing or outdated lines for this speaker; cached and imported takes are kept',!p.dialogue.some(l=>l.speaker===sp.id&&l.translation?.trim()))}${conversionFields(sp)}`:`<div class="inspector-section-title">${I('settings',13)}DIALOGUE CLIP</div>${l?`<div class="timing-fields">${field('Start · seconds','line.start',l.start,'number','step="0.01" min="0"')}${field('End · seconds','line.end',l.end,'number','step="0.01" min="0"')}</div><label class="slider-field"><span>Clip volume<strong>${Math.round((l.gain??1)*100)}%</strong></span><input aria-label="Clip volume" data-field="line.gain" type="range" min="0" max="2" step=".05" value="${l.gain??1}"></label><label class="check-field"><input data-field="line.auto_fit" type="checkbox"${l.auto_fit!==false&&p.settings.fit_duration!==false?' checked':''}>Auto-fit this clip · 0.80–1.25×</label><label class="slider-field"><span>Manual speech speed<strong>${Math.round((l.playback_rate??1)*100)}%</strong></span><input aria-label="Manual speech speed" data-field="line.playback_rate" type="range" min=".8" max="1.25" step=".01" value="${l.playback_rate??1}"></label>${field('Estimate pace · words/minute','settings.estimated_speech_wpm',p.settings.estimated_speech_wpm??150,'number','min="80" max="240" step="5"')}<p class="inspector-note">Timing estimates use this pace and are approximate. Moving the speed slider turns off auto-fit for this clip. Speed changes apply during playback and render.</p>${button('import-take',I('upload',13)+'Import replacement take','secondary full-width')}${timingActions(l)}${l.warning&&!l.audio?`<p class="warning-box">${H(l.warning)}</p>`:''}<p class="inspector-note">Use imported takes from another local tool, or generate a voice here. Export checks timing.</p>`:'<p class="inspector-note">Select a dialogue clip to edit timing and volume.</p>'}<div class="inspector-section-title divider-top">${I('layers',13)}SOURCE TRACKS</div>${['video','audio','subtitle'].map(kind=>select(`${kind[0].toUpperCase()+kind.slice(1)} track`,`settings.${kind}_stream`,opt('','None',p.settings[`${kind}_stream`]===null)+(p.media?.streams??[]).filter(s=>s.type===kind).map(s=>opt(s.index,`#${s.index} · ${s.language} · ${s.codec}`,s.index===p.settings[`${kind}_stream`])).join(''))).join('')}`}
  <div class="inspector-section-title divider-top">${I('cpu',13)}PROJECT MODELS${button('models',I('settings',13),'icon-button','Configure models')}</div><div class="mini-models">${['separation','translation','synthesis'].map(cap=>{const m=S.models.find(x=>x.id===p.models[cap].id);return button('models',`<span>${cap==='synthesis'?'Voice':cap[0].toUpperCase()+cap.slice(1)}</span><strong>${H(m?.label.split(' · ')[0]??p.models[cap].id)}</strong><span class="model-dot ${m?.available?'installed':''}"></span>`);}).join('')}</div></fieldset>`;}
function row(label,ic,body,video=false,muted=false,color='',track='',id=''){
  const visual=['video','subtitles'].includes(track),action=visual?(muted?'Show':'Hide'):(muted?'Unmute':'Mute'),title=`${action} ${label}`;
  const extra=`data-track="${track}" data-id="${H(id)}" aria-label="${H(title)}" aria-pressed="${muted}"`;
  return `<div class="timeline-row ${video?'video-row':''} ${muted?'track-muted':''}" ${track==='speaker'?`data-speaker-lane="${H(id)}"`:''}><div class="track-label">${track==='speaker'?`<span class="track-grip" data-reorder-speaker="${H(id)}" role="button" tabindex="0" title="Drag to reorder speaker tracks; use arrow keys when focused">${I('grip',10)}</span>`:I('grip',10,'track-grip')}${track?button('toggle-track',I(ic,13),'track-icon',title,locked(),extra):I(ic,13)}<span class="track-name" ${color?`style="color:${color}"`:''}>${H(label)}</span>${track?button('toggle-track',I(visual?(muted?'eye-off':'eye'):(muted?'volume-off':'volume'),13),'track-control',title,locked(),extra):''}</div><div class="track-body">${body}</div></div>`;
}
function renderTimeline(){const content=$('.timeline-content');if(!content)return;const p=S.p,scale=pps(),d=duration();content.style.width=`${186+d*scale}px`;const step=d>120?Math.max(10,Math.ceil(d/100)*10):2;content.innerHTML=`<div class="ruler"><div class="track-label ruler-label">${I('clock',12)}<span>TIME</span></div><div class="ruler-ticks" data-seek>${Array.from({length:Math.ceil(d/step)},(_,i)=>`<span style="left:${i*step*scale}px">${time(i*step)}</span>`).join('')}</div></div>`+
  row('Video','film',`<div class="video-strip" data-seek>${Array.from({length:Math.max(8,Math.min(30,Math.ceil(S.zoom*8)))},()=>`<div class="thumbnail">${p.assets.preview?`<span>${I('film',20)}<small>${H(p.media.name)}</small></span>`:station()}</div>`).join('')}${!p.media?'<span class="sample-track-tag">SAMPLE VISUAL · NO SOURCE VIDEO</span>':''}</div>`,true,p.settings.video_visible===false,'','video')+
  row('Original dialogue','mic',`<div class="wave-strip original-strip">${wave(p.assets.vocals??p.assets.original_audio,'#79838b',p.demo)}${!p.assets.original_audio?`<span class="wave-placeholder">${p.demo?'Sample waveform':'Prepare media to extract audio'}</span>`:''}</div>`,false,Boolean(p.settings.original_muted),'','original')+
  row('Music & effects','audio',`<div class="wave-strip background-strip">${wave(p.assets.background,'#65b4a5',p.demo)}${!p.assets.background?`<span class="wave-placeholder">${p.demo?'Sample waveform':'Separate audio to create a background stem'}</span>`:''}</div>`,false,Boolean(p.settings.background_muted),'','background')+
  p.speakers.map(s=>row(s.name,'mic',`<div class="clip-lane">${p.dialogue.filter(l=>l.speaker===s.id).map(l=>`<div class="dialogue-clip ${l.id===S.selected?'selected':''} ${l.audio?'has-take':''}" data-act="select-line" data-id="${H(l.id)}" style="left:${l.start*scale}px;width:${Math.max(10,(l.end-l.start)*scale)}px;--clip-color:${s.color}" role="button" tabindex="0" title="${H(s.name+' · '+(l.translation||l.source||'New line'))}"><span class="trim-handle left" data-trim="start" data-id="${H(l.id)}"></span><span class="clip-text">${I(l.audio?'audio':'circle',l.audio?11:9)}<span>${H(l.translation||l.source||'New line')}</span></span><span class="clip-timing-dot timing-${timingInfo(p,l).status}" data-timing-id="${H(l.id)}" title="${H(timingInfo(p,l).label)}"></span><span class="trim-handle right" data-trim="end" data-id="${H(l.id)}"></span></div>`).join('')}</div>`,false,Boolean(s.muted),s.color,'speaker',s.id)).join('')+
  row('English subtitles','subtitles',`<div class="clip-lane">${p.dialogue.map(l=>button('select-line',H(l.translation||l.subtitle||'Untranslated'),`subtitle-clip ${l.id===S.selected?'selected':''}`,'',false,`data-id="${H(l.id)}" style="left:${l.start*scale}px;width:${Math.max(10,(l.end-l.start)*scale)}px"`)).join('')}</div>`,false,p.settings.subtitles_visible===false,'','subtitles')+`<div class="playhead" style="left:${186+S.time*scale}px"><span></span><i></i></div>`;}
function dialogueTable(){return `<div class="dialogue-table-wrap"><table class="dialogue-table"><thead><tr><th>#</th><th>Time</th><th>Speaker</th><th>Japanese source</th><th>English adaptation</th><th>Voice</th></tr></thead><tbody>${S.p.dialogue.map((l,i)=>{const s=S.p.speakers.find(s=>s.id===l.speaker);return `<tr tabindex="0" data-act="select-line" data-id="${H(l.id)}" class="${l.id===S.selected?'selected':''}"><td>${String(i+1).padStart(2,'0')}</td><td>${time(l.start)} – ${time(l.end)}</td><td><span class="speaker-dot" style="background:${s.color}"></span>${H(s.name)}</td><td>${H(l.source||'—')}</td><td>${H(l.translation||'—')}</td><td>${I(l.audio?'checked':'circle',13,l.audio?'green':'')}</td></tr>`;}).join('')}</tbody></table>${!S.p.dialogue.length?'<p class="table-empty">Import subtitles or transcribe the source to begin.</p>':''}</div>`;}
function jobsView(){return `<div class="jobs-list">${S.jobs.length?S.jobs.map(j=>`<div class="job-row job-${j.status}"><span class="job-icon">${I(j.status==='completed'?'checked':active(j)?'loader':'activity',17,active(j)?'spin':'')}</span><div><strong>${H(j.kind[0].toUpperCase()+j.kind.slice(1))}<span>${H(j.status)}</span></strong><p>${H(j.message)}</p>${j.result?.warnings?.length?`<details class="job-warnings"><summary>Timing warnings (${j.result.warnings.length})</summary><ul>${j.result.warnings.map(w=>`<li>${H(w)}</li>`).join('')}</ul></details>`:''}${active(j)?`<div class="progress-bar"><i style="width:${j.progress*100}%"></i></div>`:''}</div>${active(j)?button('cancel',I('x',12)+'Cancel','secondary','',false,`data-id="${j.id}"`):['failed','cancelled','interrupted'].includes(j.status)?button('job',I('refresh',12)+'Retry','secondary','Retry using current project settings',locked(),`data-kind="${j.kind}"`):j.kind==='export'&&j.result.export?`<a class="secondary" href="${asset(j.result.export)}" download>${I('download',12)}Download</a>`:''}</div>`).join(''):`<div class="empty-jobs">${I('activity',24)}<p>Your processing history will appear here.</p></div>`}</div>`;}

function renderModal(){const host=$('#modal-root');if(!host)return;if(!S.modal){host.innerHTML='';return;}const title={separation:'Separate dialogue and background.',models:'Your models. Your machine.',export:'Finish your English dub.',projects:'Project library',help:'A local dubbing workspace.'}[S.modal];host.innerHTML=`<div class="modal-backdrop"><section class="modal modal-${S.modal}" role="dialog" aria-modal="true" aria-label="${H(title)}"><div class="modal-heading"><div><span class="eyebrow">KOTO STUDIO</span><h2>${title}</h2></div>${button('close-modal',I('x',20),'icon-button','Close dialog')}</div>${S.modal==='separation'?separationPanel({p:S.p,adapters:S.models,catalog:separationCatalog,state:{...separationState,lineId:S.selected},busy:locked(),jobs:S.jobs,player:comparison.state}):S.modal==='models'?modelModal():S.modal==='export'?exportModal():S.modal==='projects'?projectModal():helpModal()}</section></div>`;}
async function openSeparation(){await safe(async()=>{separationCatalog=await api('/separation/models');separationState.start=Math.min(S.time,Math.max(0,duration()-.25));separationState.end=Math.min(duration(),separationState.start+30);S.modal='separation';},'Opening separation');}
function updateSeparationPlayer(state){
  if(S.modal!=='separation')return;
  const playButton=$('[data-act="play-separation"]');if(playButton)playButton.textContent=state.playing?'Pause':'Play';
  const seek=$('[data-separation-seek]');if(seek)seek.value=state.time;
  const record=S.p?.separations?.find(r=>r.id===state.resultId);const clock=$('#separation-clock');if(clock&&record)clock.textContent=`${precise(record.start+state.time)} / ${precise(record.end)}`;
}
function modelModal(){return `<p class="modal-intro">Choose an adapter at each stage. Workers run in isolated environments. Model files stay on your machine; first use may download weights if you select a model name rather than a local path.</p><div class="models-grid">${Object.entries(S.p.models).filter(([cap])=>cap!=='voice_conversion').map(([cap,selection])=>{const m=S.models.find(m=>m.id===selection.id);return `<fieldset class="model-card"${disabled(locked())}><div class="model-card-heading">${I('cpu',16)}<strong>${cap[0].toUpperCase()+cap.slice(1)}</strong><span class="${m?.available?'installed-badge':'missing-badge'}">${m?.available?'Worker installed':'Needs setup'}</span></div><select data-field="adapter.${cap}" aria-label="${cap} adapter">${S.models.filter(m=>m.capability===cap).map(m=>opt(m.id,m.label,m.id===selection.id)).join('')}</select><p>${H(m?.description)}</p>${modelFields(m,selection.settings,`model.${cap}`)}</fieldset>`;}).join('')}${projectConversionCard()}<div class="custom-adapter-card">${I('layers',24)}<h3>Bring another model</h3><p>Add a trusted worker to <code>models/adapters.json</code>. The protocol supports alternative separators, TTS, and TTS → voice conversion pipelines.</p>${button('help','Setup instructions'+I('chevron',13),'secondary')}</div></div><div class="modal-actions">${button('refresh-models',I('refresh',13)+'Refresh status','secondary')}${button('save-models',I('check')+'Save model settings','primary','',locked())}</div>`;}
function exportModal(){const p=S.p,voices=audibleLines(p),issues=exportIssues(p),missing=issues.filter(i=>i.type==='missing'),timing=issues.filter(i=>i.type==='timing');return `<p class="modal-intro">Track mutes and visibility are applied to the render. Hidden video becomes black. Hidden subtitles are not embedded. MKV copies visible source video; MP4 encodes H.264.</p><fieldset class="export-fields"${disabled(locked())}>${field('Project name','name',p.name)}<div class="export-format">${['mkv','mp4'].map(f=>button('format',`${I('film',21)}<strong>${f.toUpperCase()}</strong><span>${f==='mkv'?'Copy source video · AAC + SRT':'H.264 encode · AAC + timed text'}</span>${p.settings.output===f?I('check',16):''}`,p.settings.output===f?'selected':'','',false,`data-format="${f}"`)).join('')}</div>${select('Background audio','settings.background_mode',['separated','original','silence'].map((v,i)=>opt(v,['Separated music & effects','Original mix — includes original dialogue','Silence — English voices only'][i],p.settings.background_mode===v)).join(''))}<div class="two-fields">${['background_gain','dialogue_gain'].map((key,i)=>`<label class="slider-field"><span>${i?'Dialogue':'Background'} level<strong>${Math.round(p.settings[key]*100)}%</strong></span><input data-field="settings.${key}" type="range" min="0" max="2" step=".05" value="${p.settings[key]}"></label>`).join('')}</div><label class="check-field"><input data-field="settings.fit_duration" type="checkbox"${p.settings.fit_duration?' checked':''}>Fit voice takes to line duration within a modest speed range</label></fieldset><div class="export-readiness">${I('checked',17)}<span><strong>${voices.filter(l=>l.audio).length} / ${voices.length} unmuted voices ready</strong><small>${!p.media?'Import source video before rendering.':missing.length?`${missing.length} clip${missing.length===1?' needs':'s need'} replacement audio before rendering.`:timing.length?`${timing.length} clip${timing.length===1?' exceeds its slot':'s exceed their slots'}. You can still render.`:'Voice takes fit their slots. Export verifies the actual audio.'}</small></span></div>${timing.length?`<p class="export-timing-warning" role="status">Recommended: fix audio timing before exporting. ${missing.length?'Add the missing voice takes to render.':'You can still render anyway.'} Long takes play in full and may overlap later dialogue. Audio past the video end extends the export.</p>`:''}${issues.length?`<div class="export-issues">${issues.map(({line:l,index,reason})=>`<div class="export-issue"><strong>Line ${index+1} · ${H(p.speakers.find(s=>s.id===l.speaker)?.name??l.speaker)} · ${time(l.start)}</strong><p>${H(l.translation||l.source||'Untitled clip')}</p><small>${H(reason)}</small><div>${button('review-timing','Review clip','secondary','Open this clip in the editor',false,`data-id="${H(l.id)}"`)}${timingActions(l)}</div></div>`).join('')}</div>`:''}${p.assets.export?`<div class="download-row"><a class="secondary" href="${asset(p.assets.export)}" download>${I('download')}Latest video</a><a href="${asset(p.assets.english_subtitles)}" download>Subtitles</a><a href="${asset(p.assets.dub_audio)}" download>Dub audio</a></div>`:''}<div class="modal-actions">${button('close-modal','Back to editor','secondary')}${button('render',I('download',15)+(timing.length&&!missing.length?'Render anyway':'Render English dub'),'primary','',locked()||!p.media||!p.dialogue.length||missing.length>0)}</div>`;}
function projectModal(){return `<div class="project-list">${S.projects.map(p=>button('open-project',`<span class="project-icon">${I('film',21)}</span><span><strong>${H(p.name)}</strong><small>Edited ${new Date(p.updated*1000).toLocaleString()}</small></span>${p.id===S.p.id?'<span class="tiny-tag">OPEN</span>':I('chevron',16)}`,'','',false,`data-id="${p.id}"`)).join('')}</div><div class="modal-actions"><a class="secondary" href="/api/projects/${S.p.id}/download" download>${I('download',13)}Project JSON</a>${button('new-project',I('plus',15)+'New project','primary')}</div>`;}
function helpModal(){return `<p class="modal-intro">Local-first dubbing for Windows + NVIDIA. This release includes media preparation, editable dialogue and speakers, model workers, and export. Image restoration and automatic lip sync are not included.</p><div class="help-grid"><div><h3>${I('layers',16)}Start a project</h3><ol><li>Import video, choose tracks, and Prepare.</li><li>Separate audio, transcribe Japanese, and diarize speakers. Or import subtitles and assign speakers manually.</li><li>Review the English adaptation and attach speaker references.</li><li>Generate or import each English voice take.</li><li>Review timing and export the completed mix.</li></ol></div><div><h3>${I('cpu',16)}Install model workers</h3><p>Double-click <code>Install-Models.cmd</code> to choose local workers. Each worker uses the app's private Python and CUDA libraries.</p><code class="command-block">Install.cmd — Python + FFmpeg<br>Install-Models.cmd — optional voice/audio workers<br>Install-Translation.cmd — local Ollama + Qwen3<br>Install-Separation.cmd — UVR-style workers<br>Install-Diarization.cmd — local speaker weights<br>Install-Piper.cmd — install or repair default voices<br>Install-Reference-Voices.cmd — local XTTS</code><p>Piper setup downloads an English voice. Diarization setup needs a Hugging Face read token and accepted model access agreements. Run Install-Reference-Voices.cmd to download XTTS weights and enable original speaker references. Runtime files and caches stay in this app folder.</p></div></div><div class="help-note">${I('headphones',17)}<span>Without AI workers, you can import subtitles, attach replacement takes, and render a finished video. Inference is never simulated.</span></div><div class="keyboard-help"><span><kbd>Space</kbd> Play / pause</span><span><kbd>Ctrl S</kbd> Save now</span><span><kbd>Delete</kbd> Delete selected clip</span><span><kbd>Ctrl Z</kbd> Undo</span><span><kbd>Ctrl Shift Z</kbd> Redo</span></div><div class="modal-actions">${button('sample',I('film')+'New sample project','secondary')}${button('models',I('settings')+'Configure models','primary')}</div>`;}
function renderToasts(){const host=$('#toast-root');if(!host)return;host.innerHTML=(S.busy?`<div class="busy-toast">${I('loader',16,'spin')}${H(S.busy)}…</div>`:S.notice?`<div class="notice-toast">${I('checked',15)}${H(S.notice)}</div>`:'')+(S.error?`<div class="error-toast" role="alert"><span>${H(S.error)}</span><div>${button('reload-project','Reload saved','')}${button('dismiss-error',I('x',15),'icon-button','Dismiss error')}</div></div>`:'');}

root.addEventListener('input',e=>{
  const el=e.target,key=el.dataset.field;
  if(el.dataset.separationRange){separationState[el.dataset.separationRange]=Number(el.value);return;}
  if(el.hasAttribute?.('data-separation-seek')){comparison.seek(Number(el.value));return;}
  if(!key)return;
  if(key==='autosave'){S.autosave=el.checked;try{localStorage.setItem('koto-autosave',S.autosave?'on':'off');}catch{}if(S.autosave){S.saveError='';scheduleAutosave();}else clearTimeout(autosaveTimer);updateDirty();return;}
  if(key==='zoom'){S.zoom=Number(el.value);renderTimeline();updateTransport();void drawWaves();return;}
  let v=el.type==='checkbox'?el.checked:['number','range'].includes(el.type)?Number(el.value):el.value;
  if(locked())return;
  let redraw=false;
  edit(p=>{
    if(key==='name')p.name=v;
    else if(key.startsWith('line.')){const prop=key.slice(5);if(prop==='speaker')moveClip(p,line().id,v);else {if(['start','end'].includes(prop))preserveSource(line());line()[prop]=v;if(prop==='playback_rate')line().auto_fit=false;if(prop==='auto_fit'&&v)p.settings.fit_duration=true;}if(['translation','speaker'].includes(prop)&&line().audio?.kind==='generated')line().audio=null;redraw=prop==='speaker';}
    else if(key.startsWith('speaker.')){const prop=key.slice(8);if(prop==='adapter'){const m=S.models.find(m=>m.id===v);speaker().voice={adapter:v||undefined,settings:v?Object.fromEntries((m?.fields??[]).map(f=>[f.key,f.default])):{}};redraw=true;}else {speaker()[prop]=v;if(prop==='use_source_reference'){const effective=S.models.find(m=>m.id===(speaker().voice.adapter||p.models.synthesis.id));if(v&&!effective?.supports_reference){const m=S.models.find(m=>m.id==='xtts');speaker().voice={...speaker().voice,adapter:'xtts',settings:Object.fromEntries((m?.fields??[]).map(f=>[f.key,f.default]))};}redraw=true;}}if(prop!=='name')invalidateSpeakerTakes(p,speaker().id);}
    else if(key.startsWith('voice.')){const s=speaker();s.voice.settings={...s.voice.settings,[key.slice(6)]:v};invalidateSpeakerTakes(p,s.id);}
    else if(key==='project-conversion'){if(!v)delete p.models.voice_conversion;else{const m=S.models.find(m=>m.id===v);p.models.voice_conversion={id:v,settings:Object.fromEntries((m.fields??[]).map(f=>[f.key,f.default]))};}redraw=true;}
    else if(key==='speaker-conversion'){const s=speaker();s.voice.conversion_disabled=v==='none';if(v&&v!=='none'){const m=S.models.find(m=>m.id===v);s.voice.conversion={id:v,settings:Object.fromEntries((m.fields??[]).map(f=>[f.key,f.default]))};}else delete s.voice.conversion;redraw=true;}
    else if(key.startsWith('conversion.')){speaker().voice.conversion.settings[key.slice(11)]=v;}
    else if(key.startsWith('settings.')){const prop=key.slice(9);if(prop.endsWith('_stream'))v=v===''?null:Number(v);p.settings[prop]=v;}
    else if(key.startsWith('adapter.')){const cap=key.slice(8),m=S.models.find(m=>m.id===v);p.models[cap]={id:v,settings:Object.fromEntries((m.fields??[]).map(f=>[f.key,f.default]))};redraw=true;}
    else if(key.startsWith('model.')){const [,cap,prop]=key.split('.');p.models[cap].settings[prop]=v;if(cap==='separation'&&prop==='model'){const model=separationCatalog?.models.find(m=>m.id===v);for(const f of model?.fields??[])p.models[cap].settings[f.key]=f.default;redraw=S.modal==='separation';}}
  });
  if(redraw)render();
  refreshTiming();if(S.modal==='export'&&key==='settings.fit_duration')renderModal();const auto=$('[data-field="line.auto_fit"]');if(auto)auto.checked=line()?.auto_fit!==false&&S.p.settings.fit_duration!==false;
  const generate=$('[data-act="generate-line"]');if(generate)generate.disabled=!line()?.translation;
  if(el.type==='range'&&key!=='zoom'){const label=el.closest('label')?.querySelector('strong');if(label)label.textContent=`${Math.round(v*100)}%`;}
});

root.addEventListener('click',async e=>{
  const seekEl=e.target.closest('[data-seek]');if(seekEl){seek((e.clientX-seekEl.getBoundingClientRect().left)/pps());return;}
  const el=e.target.closest('[data-act]');if(!el||el.disabled)return;const act=el.dataset.act;
  if(['help','models','export'].includes(act)){S.modal=act;renderModal();return;}
  if(act==='close-modal'){comparison.stop();S.modal=null;renderModal();return;}
  if(act==='save')return safe(async()=>{await save();notify('Project saved locally');},'Saving project');
  if(act==='save-models')return safe(async()=>{await save();S.modal=null;notify('Model settings saved');},'Saving settings');
  if(act==='refresh-models')return safe(async()=>{S.models=await api('/models');S.health=await api('/health');notify('Worker status refreshed');},'Checking workers');
  if(act==='job'&&el.dataset.kind==='separate')return openSeparation();
  if(act==='refresh-separation')return safe(async()=>{[S.models,separationCatalog]=await Promise.all([api('/models'),api('/separation/models')]);notify('Separation status refreshed');},'Checking separation models');
  if(act==='download-separation-model')return job('download_separation_model',{model_id:S.p.models.separation.settings.model??'mdx-inst-hq3'});
  if(act==='separation-playhead'){separationState.start=Math.min(S.time,Math.max(0,duration()-.25));separationState.end=Math.min(duration(),separationState.start+30);renderModal();return;}
  if(act==='separation-selection'){const l=line();if(!l)return;separationState.start=l.source_start??l.start;separationState.end=Math.min(duration(),l.source_end??l.end,separationState.start+120);renderModal();return;}
  if(act==='separation-preview')return job('separate',{preview:true,start:separationState.start,end:separationState.end});
  if(act==='separation-full')return job('separate');
  if(act==='select-separation'||act==='compare-separation'){const record=S.p.separations?.find(r=>r.id===el.dataset.id);if(!record)return;separationState.resultId=record.id;comparison.load(record,el.dataset.stem??'original');renderModal();return;}
  if(act==='play-separation'){const record=S.p.separations?.find(r=>r.id===el.dataset.id);if(record)comparison.toggle(record);return;}
  if(act==='stop-separation'){comparison.stop();return;}
  if(act==='activate-separation')return safe(async()=>{await save();S.p=await api(`/projects/${S.p.id}/separations/${el.dataset.id}/activate`,{revision:S.p.revision});notify('Saved stems selected for the project');},'Switching separation');
  if(act==='job')return job(el.dataset.kind);
  if(act==='prepare-no-subtitles'){if(locked())return;edit(p=>{p.settings.subtitle_stream=null;});return job('prepare');}
  if(act==='generate-speaker')return job('synthesize',{speaker_id:speaker().id});
  if(act==='generate-line')return job('synthesize',{line_ids:[line().id]});
  if(act==='render'){S.modal=null;S.tab='Jobs';return job('export');}
  if(act==='cancel')return safe(async()=>{await api(`/jobs/${el.dataset.id}/cancel`,{});},'Cancelling');
  if(act==='import-media')return importFile('media','video/*,.mkv,.avi,.mov,.webm');
  if(act==='sub-en'||act==='sub-ja')return importFile('subtitles','.srt,.vtt,.ass,.ssa',{language:act==='sub-en'?'en':S.p.models.transcription.settings.language==='zh'?'zh':'ja'});
  if(act==='reference')return importFile(`speakers/${speaker().id}/reference`,'.wav,.mp3,.flac,.m4a,.ogg');
  if(act==='import-take')return importFile(`dialogue/${line().id}/audio`,'.wav,.mp3,.flac,.m4a,.ogg');
  if(act==='projects')return safe(async()=>{await save();S.projects=await api('/projects');S.modal='projects';},'Opening projects');
  if(act==='open-project')return safe(async()=>{await save();adopt(await api(`/projects/${el.dataset.id}`));S.jobs=[];S.modal=null;S.time=0;S.playing=false;},'Opening project');
  if(act==='new-project'||act==='sample')return safe(async()=>{await save();adopt(await api('/projects',{name:'Untitled project',demo:act==='sample'}));S.jobs=[];S.modal=null;S.time=0;S.playing=false;},'Creating project');
  if(act==='review-timing'){S.modal=null;S.tab='Timeline';S.selected=el.dataset.id;seek(line().start);render();focusSelectedClip();return;}
  if(act==='fix-timing'){if(locked())return;const l=S.p.dialogue.find(l=>l.id===el.dataset.id),fix=l&&timingFix(S.p,l);if(!fix?.kind)return;edit(p=>{const current=p.dialogue.find(x=>x.id===l.id);if(fix.kind==='speed'){current.auto_fit=true;p.settings.fit_duration=true;}else{preserveSource(current);current.end=fix.end;}current.warning='';},true);return;}
  if(act==='select-line'){S.selected=el.dataset.id;seek(line().start);render();focusSelectedClip();return;}
  if(act==='speaker'){const first=S.p.dialogue.find(l=>l.speaker===el.dataset.id);if(first){S.selected=first.id;seek(first.start);}else{S.selected=null;S.voiceSpeaker=el.dataset.id;}S.tab='Voices';render();return;}
  if(act==='tab'){S.tab=el.dataset.tab;render();return;}
  if(act==='voice-tab'||act==='timeline-tab'){S.tab=act==='voice-tab'?'Voices':'Timeline';render();return;}
  if(act==='add-line'){const id=crypto.randomUUID(),start=Math.min(S.time,duration()-.1);edit(p=>p.dialogue.push({id,start:Number(start.toFixed(2)),end:Number(Math.min(duration(),start+2.5).toFixed(2)),speaker:p.speakers[0].id,source:'',translation:'',subtitle:'',audio:null}));S.selected=id;render();return;}
  if(act==='add-speaker'){edit(p=>{const id='speaker-'+crypto.randomUUID();p.speakers.push({id,name:`Speaker ${String(p.speakers.length+1).padStart(2,'0')}`,color:['#8b8aff','#e8a96b','#62c8b5','#e181b0'][p.speakers.length%4],voice:{},reference:null});S.voiceSpeaker=id;S.selected=null;S.tab='Voices';},true);return;}
  if(act==='delete-line'){deleteSelectedClip();return;}
  if(act==='use-subtitle'){edit(()=>{line().translation=line().subtitle;},true);return;}
  if(act==='preview-take'){const l=line();preview(l?.audio?.asset,l?.audio?playbackRate(S.p,l,l.audio.duration):1);return;}
  if(act==='suggest-alternatives')return job('alternatives',{line_id:line().id});
  if(act==='use-alternative'){const l=line(),s=l?.alternatives?.suggestions?.[Number(el.dataset.index)];if(s&&typeof s.text==='string')edit(()=>{l.translation=s.text;if(l.audio?.kind==='generated')l.audio=null;delete l.alternatives;},true);return;}
  if(act==='preview-reference'){const sp=speaker();preview(sp?.use_source_reference?sp.source_reference?.asset:sp?.reference);return;}
  if(act==='build-reference')return job('reference',{speaker_id:speaker().id});
  if(act==='play'){play();return;}
  if(act==='prev'){seek([...S.p.dialogue].sort((a,b)=>b.start-a.start).find(l=>l.start<S.time-.1)?.start??0);return;}
  if(act==='next'){seek([...S.p.dialogue].sort((a,b)=>a.start-b.start).find(l=>l.start>S.time+.1)?.start??duration());return;}
  if(act==='mute'){S.muted=!S.muted;syncDub();el.classList.toggle('muted',S.muted);return;}
  if(act==='toggle-track'){if(locked())return;monitor.activate();edit(p=>toggleTrack(p,el.dataset.track,el.dataset.id),true);return;}
  if(act==='original'||act==='dub'){monitor.activate();S.listen=act==='dub'?'dub':'original';syncDub();render();return;}
  if(act==='fullscreen'){($('.preview-frame')).requestFullscreen().catch(()=>{});return;}
  if(act==='zoom-in'||act==='zoom-out'||act==='fit'){S.zoom=act==='fit'?1:Math.max(1,Math.min(32,S.zoom*(act==='zoom-in'?1.5:1/1.5)));renderTimeline();$('[data-field="zoom"]').value=S.zoom;updateTransport();void drawWaves();return;}
  if(act==='format'){edit(p=>{p.settings.output=el.dataset.format;},true);return;}
  if(act==='undo'||act==='redo'){if(locked())return;const from=act==='undo'?S.history:S.future,to=act==='undo'?S.future:S.history;if(from.length){to.push(cp(S.p));const p=from.pop();p.revision=S.p.revision;S.p=p;if(!p.dialogue.some(l=>l.id===S.selected))S.selected=p.dialogue[0]?.id??null;markDirty();render();focusSelectedClip();}return;}
  if(act==='dismiss-error'){S.error='';renderToasts();return;}
  if(act==='reload-project')return safe(async()=>{if(savePending)await savePending.catch(()=>{});adopt(await api(`/projects/${S.p.id}`));},'Reloading project');
  if(act==='reload')location.reload();
});
root.addEventListener('pointerdown',e=>{if(panelLayout.start(e)||timelineDrag.start(e))return;const handle=e.target.closest('[data-trim]');if(!handle||locked())return;S.trimming=true;e.preventDefault();e.stopPropagation();const l=S.p.dialogue.find(l=>l.id===handle.dataset.id),original=cp(l),scale=pps(),startX=e.clientX,clip=handle.closest('.dialogue-clip');let values={start:l.start,end:l.end};handle.setPointerCapture(e.pointerId);const move=ev=>{const delta=(ev.clientX-startX)/scale;if(handle.dataset.trim==='start')values.start=Math.max(0,Math.min(original.end-.05,original.start+delta));else values.end=Math.min(duration(),Math.max(original.start+.05,original.end+delta));clip.style.left=values.start*scale+'px';clip.style.width=(values.end-values.start)*scale+'px';};const finish=()=>{if(!S.trimming)return;handle.removeEventListener('lostpointercapture',finish);handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',finish);S.trimming=false;S.selected=l.id;edit(p=>{const current=p.dialogue.find(x=>x.id===l.id);if(current){preserveSource(current);Object.assign(current,{start:Number(values.start.toFixed(2)),end:Number(values.end.toFixed(2))});}},true);};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',finish,{once:true});handle.addEventListener('pointercancel',finish,{once:true});handle.addEventListener('lostpointercapture',finish,{once:true});});
root.addEventListener('dragover',e=>e.preventDefault());root.addEventListener('drop',e=>{e.preventDefault();const file=e.dataTransfer.files[0];if(file&&!locked())void importFile('media','',{},file);});
root.addEventListener('mousedown',e=>{if(e.target.classList.contains('modal-backdrop')){comparison.stop();S.modal=null;renderModal();}});
document.addEventListener('keydown',e=>{if(panelLayout.keydown(e))return;const grip=e.target.closest('[data-reorder-speaker]');if(grip&&['ArrowUp','ArrowDown'].includes(e.key)&&!locked()){e.preventDefault();const i=S.p.speakers.findIndex(s=>s.id===grip.dataset.reorderSpeaker),j=i+(e.key==='ArrowUp'?-1:1);if(S.p.speakers[j])edit(p=>reorderSpeaker(p,grip.dataset.reorderSpeaker,p.speakers[j].id,j>i),true);return;}if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();if(!locked())void safe(async()=>{await save();notify('Project saved locally');},'Saving');return;}if(e.target.isContentEditable||e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key==='Escape'){comparison.stop();S.modal=null;renderModal();return;}if(S.modal)return;if(['Delete','Backspace'].includes(e.key)&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.shiftKey){if(!e.target.closest('[data-reorder-speaker],[data-panel-resize]')&&deleteSelectedClip())e.preventDefault();return;}if(e.code==='Space'){e.preventDefault();play();}if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();$(`[data-act="${e.shiftKey?'redo':'undo'}"]`)?.click();}if(e.key==='Enter'&&e.target.dataset.act==='select-line')e.target.click();});
window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue='';}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{panelLayout.refresh();renderTimeline();updateTransport();void drawWaves();},100);});
let lastTick=performance.now();setInterval(()=>{const now=performance.now();if(S.playing&&$('#video'))S.time=$('#video').currentTime;if(S.playing&&!$('#video')){S.time+=(now-lastTick)/1000;if(S.time>=duration()){S.time=0;S.playing=false;syncDub();}updateTransport();}if(S.playing)syncDub();lastTick=now;},40);
let polling=false;setInterval(async()=>{if(!S.p||S.busy||polling||panelLayout.dragging||timelineDrag.dragging||S.trimming)return;polling=true;const pid=S.p.id;try{const [p,j]=await Promise.all([api(`/projects/${pid}`),api(`/projects/${pid}/jobs`)]);if(S.p.id!==pid)return;const old=JSON.stringify(S.jobs.map(j=>[j.id,j.status,Math.round(j.progress*100),j.message]));updateJobs(j);if(!S.dirty&&S.p.revision!==p.revision){S.p=p;if(!p.dialogue.some(l=>l.id===S.selected))S.selected=p.dialogue[0]?.id??null;render();}else if(old!==JSON.stringify(j.map(j=>[j.id,j.status,Math.round(j.progress*100),j.message]))&&!S.dirty)render();}catch(e){S.error=e.message;renderToasts();}finally{polling=false;}},1400);
async function init(){render();try{[S.health,S.models,S.projects]=await Promise.all([api('/health'),api('/models'),api('/projects')]);const last=localStorage.getItem('koto-project'),pid=S.projects.find(p=>p.id===last)?.id??S.projects[0]?.id;adopt(pid?await api(`/projects/${pid}`):await api('/projects',{name:'After the rain',demo:true}));S.jobs=await api(`/projects/${S.p.id}/jobs`);render();}catch(e){S.error=e.message;render();}}
const monitor=createMonitor(asset,message=>{S.error=message;renderToasts();});
const timelineDrag=createTimelineDrag(root,{project:()=>S.p,locked,scale:pps,commit:fn=>{const next=cp(S.p);if(fn(next))edit(p=>Object.assign(p,next));},select:(id,moved)=>{if(id){S.selected=id;if(!moved)seek(line().start);}render();if(id)focusSelectedClip();}});
const panelLayout=createPanelLayout(root,()=>{renderTimeline();updateTransport();void drawWaves();});
root.addEventListener('dblclick',e=>panelLayout.reset(e));
void init();
